package com.rezics.jena;

import static org.junit.Assert.*;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.apache.jena.atlas.json.JSON;
import org.apache.jena.atlas.json.JsonObject;
import org.apache.jena.query.DatasetFactory;
import org.apache.jena.sparql.core.DatasetGraph;
import org.junit.Test;

/** Actual TS writer envelopes, checked with the unchanged native scope validator. */
public class NativeCreditBootstrapReviewTest {
    @SuppressWarnings("unchecked")
    private void acceptsWriterEnvelope(boolean agent, String role) throws Exception {
        JsonObject captured = JSON.parse(Files.readString(Path.of("src/test/resources/g2849-bootstrap-commands.json")));
        assertEquals("c6fe65a55551065e117e9ac81efd436e6b33341d", captured.get("pin").getAsString().value());
        assertEquals(4, captured.get("envelopes").getAsArray().size());
        JsonObject command = null;
        for (var item : captured.get("envelopes").getAsArray()) {
            var entry = item.getAsObject();
            if (entry.get("agent").getAsBoolean().value() == agent
                && entry.get("role").getAsString().value().equals(role)) command = entry.get("command").getAsObject();
        }
        assertNotNull(command);
        String receipt = command.get("receipt").getAsString().value();
        String update = command.get("update").getAsString().value();
        assertEquals(0, command.get("validations").getAsArray().size());
        CommandPolicy.Plan plan = CommandPolicy.parse(update, receipt);
        assertFalse(plan.current().isEmpty());
        assertFalse(plan.revisions().isEmpty());
        var profiles = ProfileRegistry.load(Path.of("profiles"));
        var service = new CommandService(profiles, "1".repeat(64).getBytes(),
            "2".repeat(64).getBytes(), "3".repeat(64).getBytes());
        Method scope = CommandService.class.getDeclaredMethod("validateScope", DatasetGraph.class,
            String.class, CommandPolicy.Plan.class, List.class, Set.class, Set.class, Set.class, Map.class);
        scope.setAccessible(true);
        var data = DatasetFactory.createTxnMem().asDatasetGraph();
        try {
            Map<String, Object> actual = (Map<String, Object>) scope.invoke(service, data, receipt, plan,
                List.of(), Set.of(), Set.of(), Set.of(), Map.of());
            System.out.println("G2849 " + (agent ? "Agent" : "external") + " " + role + " scope result: " + actual);
            assertNull("Actual retained bootstrap writer must pass the native product scope gate", actual);
        } finally { data.close(); }
    }

    @Test public void historicalAgentBootstrap() throws Exception { acceptsWriterEnvelope(true, "artist"); }
    @Test public void historicalExternalBootstrap() throws Exception { acceptsWriterEnvelope(false, "artist"); }
    @Test public void performerAgentBootstrap() throws Exception { acceptsWriterEnvelope(true, "performer"); }
    @Test public void performerExternalBootstrap() throws Exception { acceptsWriterEnvelope(false, "performer"); }
}

